def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    desperate_count = 0
    rich_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            if opp.get('budget', 0) > budget:
                rich_count += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                try:
                    prev_bids.append(float(bid))
                except Exception:
                    pass

    if budget <= 0:
        return 0

    if not alive_opponents:
        return min(budget, 21)

    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    max_prev = max(prev_bids) if prev_bids else 0.0

    supply_pressure = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_pressure < 0:
        supply_pressure = 0.0
    if supply_pressure > 1:
        supply_pressure = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 0.75
    elif hp <= 4:
        urgency += 0.4
    if no_water_days >= 2:
        urgency += 0.7
    elif no_water_days >= 1:
        urgency += 0.35

    market = 0.0
    if prev_bids:
        market += min(1.0, max_prev / DAILY_SALARY)
        market += min(1.0, avg_prev / DAILY_SALARY) * 0.5
    market += 0.15 * desperate_count
    market += 0.08 * rich_count
    market += 0.5 * supply_pressure

    base = DAILY_SALARY * (0.28 + 0.32 * supply_pressure)

    if urgency >= 1.0:
        bid = max(base, DAILY_SALARY * 0.92)
    elif urgency >= 0.5:
        bid = max(base, DAILY_SALARY * (0.68 + 0.12 * supply_pressure))
    else:
        if max_prev >= DAILY_SALARY * 0.9 and hp > 3 and no_water_days == 0:
            bid = DAILY_SALARY * 0.22
        elif prev_bids:
            target = max(avg_prev + 1.5, max_prev * 0.78)
            bid = max(base, min(target, DAILY_SALARY * 0.88))
        else:
            bid = base

    if day >= 8:
        bid += 4
    if hp <= 3:
        bid += 5
    if no_water_days >= 1:
        bid += 6

    if budget < DAILY_SALARY * 0.6:
        bid = min(bid, budget)
    else:
        bid = min(bid, budget, DAILY_SALARY)

    if hp > 4 and no_water_days == 0 and supply >= 23:
        bid = min(bid, DAILY_SALARY * 0.35)

    if bid < 0:
        bid = 0
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    alive_opponents = [o for o in opponents_status.values() if o.get('alive', False)]
    if not alive_opponents:
        return min(my_status.get('budget', 0.0), DAILY_SALARY * 0.4)

    # Read yesterday's bids for immediate reaction
    yesterday_bids = []
    for opp_id, opp in opponents_status.items():
        if not opp.get('alive', False):
            continue
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        # Threshold: if they were bidding aggressively yesterday, they likely continue.
        aggressive_threshold = DAILY_SALARY * 0.85

        if highest_prev_bid >= aggressive_threshold:
            # If we are healthy, slightly undercut; if low HP, match more.
            if hp > 3:
                bid = DAILY_SALARY * 0.30
            else:
                bid = DAILY_SALARY * 0.85
        else:
            # If they were moderate, aim to beat the leader by a small margin.
            bid = max(DAILY_SALARY * 0.50, highest_prev_bid + 1.5)
    else:
        # No signal: bid based on our HP.
        if hp <= 2:
            bid = DAILY_SALARY * 0.90
        elif hp <= 3:
            bid = DAILY_SALARY * 0.70
        else:
            bid = DAILY_SALARY * 0.55

    # Supply-aware adjustment: if supply is near minimum, slightly increase to secure water.
    # Use only safe arithmetic; no list indexing.
    try:
        if supply <= 16.0:
            bid *= 1.10
        elif supply >= 22.0:
            bid *= 0.95
    except Exception:
        pass

    # Never bid more than we can afford.
    bid = min(budget, bid)

    # Keep bids non-negative.
    if bid < 0.0:
        bid = 0.0

    return bid

